pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Initial owner is deployer (this contract)
        address newOwner = address(0x1234567890123456789012345678901234567890);
        vm.prank(address(this));
        c.setOwner(newOwner);
        // Reference: owner == newOwner; bug: owner == 0x0000000000000000000000000000000000000001
        assertTrue(c.owner() != address(0x0000000000000000000000000000000000000001));
    }
}

