// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address attacker = address(0x1234);
        address newOwner = address(0x5678);

        // attacker tries to set owner
        vm.prank(attacker);
        (bool success, bytes memory data) = address(c).call(abi.encodeWithSelector(c.setOwner.selector, newOwner));

        // In reference, call reverts; in bug, call succeeds
        // Here we check that owner is still the deployer (original) – this holds for reference, fails for bug
        assertTrue(c.owner() != newOwner);
    }
}

